     "note": "输入由“模拟用户”实时决定：每轮看完剧情，由 LLM 按 Vicky 的习惯（反问、要说法、设条件、主动靠近；约一半点选项）决定点 A/B 还是自己打一句。在 V0.17b（10+10 第 1 段首尾帧锁）基础上，修了锁帧暴露的问题：①末帧质检加“背景变成灰色影棚或纯色”，找不到干净帧就只把背景换回当前地点；②锁帧前把末帧回正——贴脸特写（脸框宽超过 0.7）往前最多找 4.5 秒挑标准近景，站远的裁到脸宽约三分之一；③并排坐时每个近景和收尾都写成三分之四侧脸，质检也查“正对镜头像坐在对面”；④契约写成没有字的素面纸。结果：无硬错误 13/18（V0.17b 12/18），第 11 轮吻戏，第 13 轮演到 K13。这四类问题全部清零（末帧毛病被锁进 10 秒 3→0、车内正对镜头 2→0、契约满页字 1→0），18 轮里有 5 轮的末帧被回正。剩下的 5 个硬错误都是第 2 段随机出的：车内座椅变酒红（第 3 轮）、你手上多了戒指和车窗外像白天（第 4 轮）、西装在强光里变浅灰（第 5 轮）、Selene 裙子成了低胸 V 领（第 8 轮）、手发黑显老并跳回室内（第 18 轮）。另有两轮末尾 4.5 秒全是贴脸特写、没找到标准帧（第 10、11 轮），这次没造成硬错误，但回正还需要一个兜底。时延：这组是 Vivix 故障恢复后跑的，只算生成的中位从上次 41 秒涨到 77 秒，发送到就绪中位 128.9 秒，主要是服务端变慢，不能和上一版直接比。",
